class StoredLocation(BaseModel):
    """The ``StoredLocation`` object.

    The value of v1:location:<place>: where a postcode is, as looked up at fetched_at, or that it isn't
    one postcodes.io or Kartverket know. `found` and `location` go together: a found postcode has a
    location, and one that wasn't found has none.
    """

    fetched_at: datetime
    postcode: str = Field(
        description=(
            'As v1:sub:postcode has it ("SE17 3LL", "0150"); for a weather key\'s, the postcode or district it stands '
            'for ("SE17").'
        ),
    )
    found: bool = Field(description="False for a postcode that doesn't exist (a typo, or one that's been terminated).")
    location: Postcode | None = Field(default=None, description="Where it is; null when it wasn't found.")


class StoredPlayer(BaseModel):
    """The value of v1:spotify:<device id>.

    Each service's part is in Spotify's own shape (/me/player/queue: its currently_playing, null when
    nothing plays, and its queue; Apple Music's made to look like it, from the last played track and the
    ones before it), null when the service is off for the device or couldn't be fetched.
    `spotify_playback` is how far into the track Spotify was, which is fetched far more often than the
    queue while something plays (see the `pace` key), so it has a time of its own.
    """

    fetched_at: datetime
    spotify: MusicQueue | None = None
    apple_music: MusicQueue | None = None
    spotify_playback: SpotifyPlayback | None = None


class StoredTop(BaseModel):
    """The ``StoredTop`` object.

    The value of v1:spotify-top:<device id>: each service's top lists by Spotify's time range
    ("long_term", "short_term"), each its /me/top/tracks and /me/top/artists answers, null when the
    service is off for the device or couldn't be fetched.
    """

    fetched_at: datetime
    spotify: MusicTopLists | None = None
    apple_music: MusicTopLists | None = None


SubChanged = Literal[""]
"""The nudge on v1:sub:changed carries nothing."""


Subscription = list[Annotated[str, Field(min_length=1)]]
"""A subscription set's members, in no order. See `sources` for each source's."""


class TouchscreenQuietHours(BaseModel):
    """The ``TouchscreenQuietHours`` object.

    A stretch of the day when a touchscreen's screen sleeps soon after the last touch, whatever
    sleep_minutes says. The times are the touchscreen's own local time, as minutes after midnight; an
    end before the start runs past midnight, and equal times are never quiet. Off keeps the times for
    next time. A display without it (one saved before it existed) has no quiet hours. Only a Raspberry
    Pi kiosk sleeps its screen: a touchscreen in a browser keeps the setting but ignores it.
    """

    on: bool = Field(description="Whether the quiet hours apply.")
    start: MinuteOfDay = Field(description="A time of day, as minutes after midnight (0 to 1439).")
    end: MinuteOfDay = Field(description="A time of day, as minutes after midnight (0 to 1439).")


class TouchscreenDisplay(BaseModel):
    """A touchscreen's screen itself."""

    sleep_minutes: Literal[0, 2, 5, 15, 30] = Field(
        description=(
            "Idle minutes, with no music playing, before the screen sleeps; 0 keeps it on. Only a Raspberry Pi kiosk "
            "sleeps its screen: a touchscreen in a browser keeps the setting but ignores it."
        ),
    )
    brightness: Annotated[int, Field(ge=10, le=100)] = Field(
        default=100,
        description=(
            "How bright the screen is while someone uses it, as a percentage of its full brightness. Only a "
            "touchscreen that can set its screen's brightness (its config's brightness_control) uses it: any other "
            "keeps the setting but ignores it. The server always sends it; left out is 100, so a config from before it"
            " was added reads the same."
        ),
    )
    quiet_hours: TouchscreenQuietHours | None = Field(
        default=None,
        description=(
            "A stretch of the day when a touchscreen's screen sleeps soon after the last touch, whatever sleep_minutes"
            " says. The times are the touchscreen's own local time, as minutes after midnight; an end before the start"
            " runs past midnight, and equal times are never quiet. Off keeps the times for next time. A display "
            "without it (one saved before it existed) has no quiet hours. Only a Raspberry Pi kiosk sleeps its screen:"
            " a touchscreen in a browser keeps the setting but ignores it."
        ),
    )


class TouchscreenLyrics(BaseModel):
    """How a touchscreen shows a song's synced lyrics.

    A config without it (one saved before it existed) shows them at medium size, lined up on the left.
    """

    size: Literal["small", "medium", "large", "x-large"] = Field(
        description=(
            "The lyrics' type size: medium is the size the touchscreen works out from its lyrics panel, and small, "
            "large and x-large are 0.8, 1.2 and 1.4 times that."
        ),
    )
    align: Literal["left", "center", "right"] = Field(description="Which side the lines line up on.")


class TouchscreenStyle(BaseModel):
    """How a touchscreen looks."""

    skin: Literal["day", "auto", "night"] = Field(
        description=(
            "day or night, or auto to follow the sun at its location (day from sunrise to sunset), which a touchscreen"
            " that doesn't know its location shows as day."
        ),
    )
    colour: Literal["forest", "navy", "teal", "plum", "terracotta", "pink", "yellow", "black", "violet", "dynamic"] = (
        Field(
            description=(
                "The colour, in both skins; violet's play button is a gradient. dynamic is the old dynamic: true, over "
                "forest."
            ),
        )
    )
    dynamic: bool = Field(
        default=False,
        description=(
            "Whether the day skin's colours follow the album art while music plays, fading back to the colour once it "
            "has stopped for a while."
        ),
    )


class TouchscreenConfig(ConfigBase):
    """A touchscreen's config (ConfigResponse with type touchscreen).

    It draws itself from it, and saves it from its own settings, as its owner does on the settings site.
    It is paired by token, so it has no pairing code; it keeps its own time, so it has no time zone or
    interval; and it plays music itself, so it has no music or other integrations' sections but parcels,
    whose notices join its notice board. Its Wi-Fi stays on the device, never here.
    """

    type: Literal["touchscreen"]
    brightness_control: bool = Field(
        default=False,
        description=(
            "Whether the touchscreen can set its screen's brightness, as it reported at registration. The server "
            "always sends it; left out is false."
        ),
    )
    language: Literal["en", "nb"] = Field(
        default="en",
        description=(
            "The language of everything the touchscreen shows, as a BCP 47 code (nb is Norwegian Bokmål). The server "
            "always sends it; left out is en, so a config from before it was added reads the same."
        ),
    )
    style: TouchscreenStyle = Field(description="How a touchscreen looks.")
    display: TouchscreenDisplay = Field(description="A touchscreen's screen itself.")
    lyrics: TouchscreenLyrics | None = Field(
        default=None,
        description=(
            "How a touchscreen shows a song's synced lyrics. A config without it (one saved before it existed) shows "
            "them at medium size, lined up on the left."
        ),
    )
    parcels: Parcels | None = Field(
        default=None,
        description=(
            "Whether its notice board has the owner's parcels (DeviceNotices.parcels). The server always sends it; "
            "null or left out is off, so a config from before it was added reads the same, and a whole save "
            "(putConfig) that leaves it out keeps it as it is."
        ),
    )


class TouchscreenRegistration(BaseModel):
    """The ``TouchscreenRegistration`` object.

    What GET /register takes as its query, and its confirming page posts as a form: a touchscreen
    registering through the login.
    """

    model_config = ConfigDict(extra="forbid")

    secret_hash: SecretHash = Field(
        description=(
            "A device's secret (DeviceRegistration's), hashed: the hex SHA-256 of its UTF-8 bytes, in lower case. It's"
            " what the broker stores, and doesn't authenticate anything, so it can go in a URL where the secret can't."
        ),
    )
    width: ScreenSize = Field(description="A screen's width or height, in pixels.")
    height: ScreenSize = Field(description="A screen's width or height, in pixels.")
    brightness_control: bool = Field(description="Whether the touchscreen can set its screen's brightness.")
    return_to: str | None = Field(
        default=None,
        description=(
            "A URL of the tablet's own app to come back to, on an origin the server allows; it gets `device_id` (or "
            "`error=taken`) added to its query."
        ),
    )


ConfigResponse = Annotated[EpaperConfig | TouchscreenConfig, Field(discriminator="type")]
"""A device's config: the value of v1:config:<device id> (with no pairing code) and, with its
pairing_code set, of v1:pairing:<device id>, and what GET and PUT /api/devices/config answer and
take. A few flat fields (who and what the device is, its size, and its clock format), then a section
per panel, each its own schema, and `style`, which every type has but whose schema is the type's
own. A touchscreen's has only what it shows itself: its language, the arrivals, the weather and the
notice board, its look, its screen's sleep and its lyrics; an e-paper screen's also has its time
zone, pairing code and the rest of its panels. `type` says which: an e-paper screen's (EpaperConfig)
or a touchscreen's (TouchscreenConfig). It never has a secret of any kind: logins and keys are the
owner's account's, held on the server. A read-only field (readOnly) is the server's, or what the
device said at registration, and isn't changed by a save.
"""
